<?php
function efQuery($db,$sql,$params=[]){$st=$db->prepare($sql);try{if($params)$st->bind_param(str_repeat('s',count($params)),...$params);$st->execute();$rs=$st->get_result();return $rs?$rs->fetch_all(MYSQLI_ASSOC):[];}finally{$st->close();}}
function efPhone($value){$p=preg_replace('/\D/','',(string)$value);return strlen($p)>=10?substr($p,-10):$p;}
function efAuthorize($admin=false){global $authconn,$companyid,$subcompanyid,$projectid,$loginid,$loginroleid;if(empty($loginid)||empty($_SESSION['sessionid'])||$_SESSION['sessionid']!==session_id())throw new RuntimeException('Login is required.');if((string)$loginroleid==='0')return;
 $mods=OnlyProject_loginmodulesdetails_frommaster($authconn,$companyid,$subcompanyid,$projectid,'allwithauth',allauthorizedmoduleid($authconn,$companyid,$subcompanyid,$projectid,$loginid));
 $allowed=['krf_enquiry_followup/enquiry_followup_admin.php'];if(!$admin)$allowed[]='krf_enquiry_followup/enquiry_followup.php';foreach((array)$mods as $m){$path=trim(str_replace('\\','/',explode('?',(string)($m['modulefoldername']??''))[0]),'/');if(in_array($path,$allowed,true))return;}throw new RuntimeException('Enquiry follow-up access is required.');}
function efRows($db,$scope,$admin,$ids=[],$lock=false){$params=array_slice($scope,0,3);$where='e.companyid=? AND e.subcompanyid=? AND e.projectid=?';if($ids){$where.=' AND e.id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$params=array_merge($params,$ids);}
 return efQuery($db,"SELECT e.*,f.id AS followup_id,f.next_followup_date,f.reason AS last_reason,f.psono AS linked_psono,f.created_at AS last_followup_at FROM krf_product_enquiries e LEFT JOIN krf_product_enquiry_followup f ON f.id=(SELECT MAX(h.id) FROM krf_product_enquiry_followup h WHERE h.enquiry_id=e.id AND h.projectid=e.projectid) WHERE $where ORDER BY e.id DESC".($lock?' FOR UPDATE':''),$params);}
function efOpen($r){return !in_array(strtolower(trim($r['status']??'')),['converted','not interested','cancelled','closed'],true);}
function efDefaultDate($r){$c=require __DIR__.'/config.php';$time=$c['default_followup_time']??'10:30';$days=max(0,(int)($c['default_followup_days']??1));if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time))throw new RuntimeException('Invalid default follow-up time.');return (new DateTimeImmutable($r['created_at'],new DateTimeZone('Asia/Kolkata')))->modify('+'.$days.' days')->format('Y-m-d').' '.$time.':00';}
function efFingerprint($rows){return hash('sha256',json_encode(array_map(fn($r)=>array_intersect_key($r,array_flip(['id','clientid','mobileno','productid','quantity','expected_date','status','updated_at','followup_id'])), $rows)));}
function efLog($db,$r,$scope,$name,$reason,$conversation,$next,$pso='') {efQuery($db,'INSERT INTO krf_product_enquiry_followup(companyid,subcompanyid,projectid,enquiry_id,enquiry_no,reason,conversation,next_followup_date,psono,created_by,created_by_name,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())',[$scope[0],$scope[1],$scope[2],$r['id'],$r['enquiry_no'],$reason,$conversation,$next,$pso,$scope[3],$name]);}
// Called INSIDE the existing PO transaction, before any inserts.
function efLockConversion($db,$token,$scope){if(!$token)return null;if(session_status()!==PHP_SESSION_ACTIVE)session_start();$p=$_SESSION['enquiry_po'][$token]??null;if(!$p||$p['expires']<time()||$p['scope']!==array_map('strval',$scope))throw new RuntimeException('Enquiry conversion expired. Reopen enquiry follow-up.');$rows=efRows($db,$scope,$p['admin'],$p['ids'],true);if(count($rows)!==count($p['ids'])||efFingerprint($rows)!==$p['fingerprint'])throw new RuntimeException('The enquiries changed or were converted. Refresh enquiry follow-up.');foreach($rows as $r)if(!efOpen($r))throw new RuntimeException('An enquiry was already closed or converted.');return $rows;}
function efCompleteConversion($db,$rows,$scope,$clientid,$pso){
 if(!$rows)return;$mapping=json_decode($_POST['enquiry_item_map']??'[]',true);if(!is_array($mapping))throw new RuntimeException('Invalid enquiry item mapping.');$byId=[];
 foreach($mapping as $m){$id=(int)($m['id']??0);$product=(string)($m['product']??'');$qty=$m['quantity']??'';if(!$product||!is_numeric($qty)||(float)$qty<=0||(float)$qty!==floor((float)$qty))throw new RuntimeException('Select an active product and enter a positive whole-number order quantity for every linked enquiry.');if(isset($byId[$id])&&$byId[$id]['product']!==$product)throw new RuntimeException('One enquiry cannot be linked to different products.');$byId[$id]=['product'=>$product,'quantity'=>($byId[$id]['quantity']??0)+(float)$qty];}
 $items=efQuery($db,'SELECT product_id,SUM(quantity) AS qty FROM krf_provisional_sales_order_items WHERE projectid=? AND psono=? GROUP BY product_id',[$scope[2],$pso]);$saved=array_column($items,'qty','product_id');$required=[];
 foreach($rows as $r){$m=$byId[(int)$r['id']]??null;if(!$m)throw new RuntimeException('A linked enquiry has no selected order product.');$required[$m['product']]=($required[$m['product']]??0)+$m['quantity'];}
 foreach($required as $id=>$qty)if(($saved[$id]??0)<$qty)throw new RuntimeException('Linked enquiry products do not match the saved PO quantities.');
 foreach($rows as $r){$m=$byId[(int)$r['id']];efQuery($db,"UPDATE krf_product_enquiries SET status='Converted',clientid=?,updated_at=NOW() WHERE id=? AND companyid=? AND subcompanyid=? AND projectid=?",[$clientid,$r['id'],$scope[0],$scope[1],$scope[2]]);efLog($db,$r,$scope,(string)($_SESSION['loginname']??$scope[3]),'Converted','Created provisional order '.$pso.' | Original enquiry: '.$r['product_name'].'; qty '.$r['quantity'].' | Chosen product ID: '.$m['product'].'; ordered qty '.$m['quantity'].' | Client reference '.$r['clientid'].' -> '.$clientid,null,$pso);}
}
